<?php

namespace Database\Seeders;

use Illuminate\Database\Seeder;
use App\Models\Notification;
use App\Models\User;

class NotificationSeeder extends Seeder
{
    public function run()
    {
        $user = User::first();
        if ($user) {
            Notification::create([
                'user_id' => $user->id,
                'type' => 'info',
                'title' => 'Test Notification',
                'message' => 'This is a test notification generated by the system.',
                'read' => false,
            ]);
            $this->command->info('Notification created for User ID: ' . $user->id);
        } else {
            $this->command->error('No users found to attach notification to.');
        }
    }
}
